input.command:
cd /root/repos/jsonschema && TMP=$(mktemp -d) && printf '{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "properties": {"foo": {"type": "string"}}
}
' > "$TMP/schema.json" && touch "$TMP/instance.jsonl" && build/src/jsonschema validate "$TMP/schema.json" "$TMP/instance.jsonl" 2> "$TMP/out.txt" 1>/dev/null; echo "--- stderr ---"; cat "$TMP/out.txt"; echo "--- verbose ---"; build/src/jsonschema validate "$TMP/schema.json" "$TMP/instance.jsonl" --verbose 2>&1 1>/dev/null; rm -rf "$TMP"
